function translateText(text,lang){var d=dictionaries[lang];if(!d||!text)return text;var trimmed=text.trim();var canonical=mixedHeadingAliases[trimmed]||trimmed;if(d[canonical])return text.replace(trimmed,d[canonical]);return text} // Homepage-safe complete phrase lookup
function translate(root,lang){if(!root||lang==='en')return;var d=dictionaries[lang];if(!d)return;var walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);var node;while((node=walker.nextNode())){var p=node.parentElement;if(!p||/^(SCRIPT|STYLE|TEXTAREA|CODE|PRE|OPTION)$/i.test(p.tagName)||p.closest('[data-no-translate]'))continue;var original=node.nodeValue;var translated=translateText(original,lang);if(translated!==original)node.nodeValue=translated;}var selector='input[placeholder],input[aria-label],input[title],button[aria-label],button[title],button[value],input[type=submit][value],a[aria-label],a[title],img[alt],img[title],select[aria-label],textarea[placeholder],textarea[aria-label]';var elements=[];if(root.nodeType===1&&root.matches&&root.matches(selector))elements.push(root);if(root.querySelectorAll)elements=elements.concat(Array.prototype.slice.call(root.querySelectorAll(selector)));elements.forEach(function(el){['placeholder','aria-label','alt','title','value'].forEach(function(a){if(el.hasAttribute(a)){var v=el.getAttribute(a),n=translateText(v,lang);if(n!==v)el.setAttribute(a,n)}})});}
