function apply(lang){if(!languages.some(function(x){return x[0]===lang}))lang='en';try{localStorage.setItem(KEY,lang);localStorage.setItem('kejun-language',lang)}catch(e){}document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';document.querySelectorAll('.kejun-language-switch').forEach(function(s){s.value=lang});document.querySelectorAll('[data-language-label]').forEach(function(el){el.textContent=(dictionaries[lang]&&dictionaries[lang].Language)||'Language'});translateDocumentMetadata(lang);translate(document.body,lang);}
window.KejunSiteI18n={language:getLang,translate:function(text){return translateText(String(text||''),getLang())}};
function addSwitcher(){if(document.querySelector('.kejun-language-switch'))return;var wrap=document.createElement('label');wrap.className='kejun-language-wrap';wrap.setAttribute('aria-label','Website language');var label=document.createElement('span');label.textContent='🌐';label.setAttribute('aria-hidden','true');var select=document.createElement('select');select.className='kejun-language-switch';select.setAttribute('aria-label','Website language');languages.forEach(function(x){var o=document.createElement('option');o.value=x[0];o.textContent=x[1];select.appendChild(o)});select.value=getLang();select.addEventListener('change',function(){/* reload from source markup to avoid translating already translated strings */try{localStorage.setItem(KEY,select.value);localStorage.setItem('kejun-language',select.value)}catch(e){}location.reload()});wrap.appendChild(label);wrap.appendChild(select);document.body.appendChild(wrap);}
var style=document.createElement('style');style.textContent='.kejun-language-wrap{position:fixed;right:14px;top:10px;z-index:9999;display:flex;align-items:center;gap:6px;padding:5px 8px;border:1px solid #cbd5e1;border-radius:8px;background:#fff;color:#172033;box-shadow:0 3px 14px #0001;font:12px Arial,sans-serif}.kejun-language-wrap select{max-width:125px;border:0;background:#fff;color:#172033;font:inherit;outline-offset:2px;cursor:pointer}.kejun-language-wrap span{font-size:15px}html[dir=rtl] body{direction:rtl}html[dir=rtl] .kejun-language-wrap{right:auto;left:14px}html[dir=rtl] input,html[dir=rtl] textarea{text-align:right}@media(max-width:760px){.kejun-language-wrap{top:7px;right:8px;padding:4px 6px}.kejun-language-wrap select{max-width:100px}}';document.head.appendChild(style);addSwitcher();var lang=getLang();if(lang!=='en')apply(lang);var obs=new MutationObserver(function(records){var l=getLang();if(l==='en')return;records.forEach(function(r){r.addedNodes.forEach(function(n){if(n.nodeType===1)translate(n,l);else if(n.nodeType===3){var t=translateText(n.nodeValue,l);if(t!==n.nodeValue)n.nodeValue=t}})})});obs.observe(document.body,{childList:true,subtree:true});
